import React, { useEffect, useState } from 'react';
import { supabase } from '../supabase';
import DashboardLayout from './DashboardLayout';

function Dashboard() {
  const [loading, setLoading] = useState(true);
  const [darkMode, setDarkMode] = useState(() => localStorage.getItem('darkMode') === 'true');
  const [isSidebarOpen, setSidebarOpen] = useState(false);
  const [activeMenu, setActiveMenu] = useState('dashboard');

  // Add the missing toggleSidebar function
  const toggleSidebar = () => {
    setSidebarOpen(!isSidebarOpen);
  };

  useEffect(() => {
    checkUser();
  }, []);

  const checkUser = async () => {
    try {
      const { data: { session } } = await supabase.auth.getSession();
      if (!session) {
        window.location.replace('/login');
        return;
      }
    } catch (error) {
      console.error('Session error:', error);
      window.location.replace('/login');
    } finally {
      setLoading(false);
    }
  };

  const handleSignOut = async () => {
    try {
      await supabase.auth.signOut();
      window.location.replace('/login');
    } catch (error) {
      console.error('Error:', error);
      window.location.replace('/login');
    }
  };

  const toggleDarkMode = () => {
    setDarkMode(prev => {
      const newMode = !prev;
      localStorage.setItem('darkMode', newMode);
      return newMode;
    });
  };

  if (loading) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-gradient-to-r from-gray-100 to-gray-200 dark:from-gray-800 dark:to-gray-900">
        <div className="text-xl text-gray-600 dark:text-gray-200">Loading...</div>
      </div>
    );
  }

  return (
    <div className={`min-h-screen ${darkMode ? 'dark' : ''}`}>
      <DashboardLayout
        darkMode={darkMode}
        toggleDarkMode={toggleDarkMode}
        isSidebarOpen={isSidebarOpen}
        toggleSidebar={toggleSidebar}
        activeMenu={activeMenu}
        setActiveMenu={setActiveMenu}
        handleSignOut={handleSignOut}
      >
        <ContentRenderer darkMode={darkMode} activeMenu={activeMenu} />
      </DashboardLayout>
    </div>
  );
}

function ContentRenderer({ darkMode, activeMenu }) {
  const content = {
    dashboard: {
      title: 'Getting Started',
      text: 'Welcome to your dashboard! You\'ve successfully logged in to your account.'
    },
    feature1: {
      title: 'Feature 1',
      text: 'This is feature 1 content.'
    },
    team: {
      title: 'Team Management',
      text: 'Manage your team members and their permissions here.'
    },
    calendar: {
      title: 'Calendar',
      text: 'Schedule and manage your appointments and deadlines.'
    }
  };

  const currentContent = content[activeMenu] || content.dashboard;

  return (
    <div className="p-4 bg-white dark:bg-gray-800 rounded-lg shadow-lg">
      <h2 className="text-xl font-semibold mb-4 text-gray-900 dark:text-white">
        {currentContent.title}
      </h2>
      <p className="text-gray-700 dark:text-gray-300">
        {currentContent.text}
      </p>
    </div>
  );
}

export default Dashboard;
